xql_query:
// ============================================================
// Rule: AZURE_Login Outside Allowed Regions
// Vendor: Microsoft EntraID
// Objective:
// Detect activity associated with AZURE_Login Outside Allowed Regions.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0001 - Initial Access
// Technique: T1078 - Valid Accounts

// Configuração inicial: define que as comparações diferenciam maiúsculas/minúsculas
config case_sensitive = true  

// Fonte de dados: preset de autenticação do Cortex XDR
// O preset 'authentication_story' consolida eventos de autenticação
// provenientes de múltiplas fontes (ex: Azure AD, Okta, VPN, etc.)
| preset = authentication_story  

// Seleção dos campos relevantes para análise de autenticações
| fields associated_products,        // Origem ou produto associado ao log (ex: Azure AD Resource Logs)
         auth_identity,              // Identidade/autenticação (UPN, e-mail, user principal)
         auth_identity_display_name, // Nome exibido do usuário autenticado
         action_country,             // País de origem da autenticação
         auth_target,                // Recurso ou serviço acessado
         action_local_ip,            // IP interno/local do dispositivo
         action_user_agent           // Agente de usuário (navegador, app, sistema etc.)

// Filtro para restringir a autenticações provenientes especificamente do Azure AD
| filter associated_products = "Azure AD Resource Logs"

// Filtro para selecionar apenas usuários cujo domínio seja "<INTERNAL_DOMAIN_29>"
| filter auth_identity contains "<INTERNAL_DOMAIN_29>"  

// Filtro para detectar logins vindos de países diferentes do Brasil e México
// (considerados regiões fora do padrão de operação)
| filter action_country not in (BRAZIL, MEXICO)
